"""Derive SkyyAccessories/build_skyyaccessories_0.5.24.py from the LIVE SkyyAccessories 0.5.23 (build_skyyaccessories_0.5.23.py = the
tools/deploy_set.py SET pin, GENERATED by tools/accessories_0_5_23_patch.py - never edit a generated script, edit this patch). Every anchor is
asserted; at the end every anchored change is undone on a copy and compared with 0.5.23 (nothing else changed). Line endings kept.
Run:  python tools/accessories_0_5_24_patch.py
      python SkyyAccessories/build_skyyaccessories_0.5.24.py
Test: python SkyyAccessories/test_skyyaccessories_0.5.24.py

0.5.24 (2026-10-17) = TEXT ONLY: the feature is called Void Charms everywhere a player or admin reads it. Skyy 2026-10-17: "i noticed they
are still called accessory's in the settings" (the Accessory Bag was renamed Void Charms in 0.5.22: /charms /charm /ch).
  1. SERVER SETUP: the section title (the kit's TITLE, published on config:def - SkyyMenu shows it as given) Accessories -> Void Charms;
     rows "Accessory slots" -> "Charm slots", "Craft from the bag" -> "Craft in Void Charms", "Accessory equipped / upgraded sound (id)"
     -> "Charm equipped / upgraded sound (id)"; help texts that said "the bag" / "bag page" / "bag slot" now say Void Charms.
  2. CHAT / PAGE LINES: craft and upgrade results ("it went straight into your Void Charms", "upgraded to X in your Void Charms - ...",
     "Void Charms already has ...", "kept in a free Void Charms slot", "... or Void Charms"), "crafting in Void Charms is switched off",
     "put it on from the Void Charms page", the profile-switch line, the empty Bonuses line, the retired Night Vision line, the
     /charms reload summary ("charm slots", "the Void Charms Craft tab").
  3. FILE HEADERS + the craft.bag / craft.autoEquip comments of NEW config / power / sounds files and the ready log line: "Server Setup -> Void Charms" (existing files keep their
     bytes - no migration).
  Unchanged on purpose: ids, config keys, file names, bridge keys, permission nodes, saved data; "Accessory Power" (Skyy's AP stat,
  popups 2026-10-16); single items stay "accessory"; "Old Accessory Bag" (the retired item's own name); the Workbench tab "Bags"; the
  config comment lines the 0.4.x / 0.5 migrations write or look for (OLD_COMMENTS / ADD_GROUPS).
  ROLLBACK to 0.5.23: safe (same files, same keys).
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

P = G.Patch(os.path.join(ROOT, "SkyyAccessories", "build_skyyaccessories_0.5.23.py"),
            os.path.join(ROOT, "SkyyAccessories", "build_skyyaccessories_0.5.24.py"))
assert P.has('VERSION = "0.5.23"\n') and P.has("tools/accessories_0_5_23_patch.py") and P.has("public boolean isOpen()"), \
    "not the generated SkyyAccessories 0.5.23 script"
HEAD = open(__file__, encoding="utf8").read().split('"""')[1]
NOTE = HEAD[HEAD.index("0.5.24 (2026-10-17)"):].rstrip() + "\n\n"

# ---- 0. docstring + version
P.rep('''"""SkyyAccessories 0.5.23 - build script (derived from the generated build_skyyaccessories_0.5.22.py by tools/accessories_0_5_23_patch.py -
edit the patch, not this file)
Run:   python build_skyyaccessories_0.5.23.py            -> SkyyAccessories/SkyyAccessories-0.5.23.jar   (deploys go through tools/deploy_set.py --yes)
Test:  python test_skyyaccessories_0.5.23.py             (harness_kit: -Xverify:all, class compare 0.5.22 -> 0.5.23, every view's commands vs its markup)

''', '''"""SkyyAccessories 0.5.24 - build script (derived from the generated build_skyyaccessories_0.5.23.py by tools/accessories_0_5_24_patch.py -
edit the patch, not this file)
Run:   python build_skyyaccessories_0.5.24.py            -> SkyyAccessories/SkyyAccessories-0.5.24.jar   (deploys go through tools/deploy_set.py --yes)
Test:  python test_skyyaccessories_0.5.24.py             (harness_kit: -Xverify:all, class compare 0.5.23 -> 0.5.24, the Void Charms texts)

''' + NOTE + '''0.5.23 (the base, still true unless 0.5.24 above says otherwise):
''')
P.rep('VERSION = "0.5.23"\n', 'VERSION = "0.5.24"\n')

# ---- 1. Server Setup: the section title + rows + help texts
P.rep('kit = CFG.emit(pool, PKG, MOD="SkyyAccessories", TITLE="Accessories",',
      'kit = CFG.emit(pool, PKG, MOD="SkyyAccessories", TITLE="Void Charms",')   # 0.5.24
P.rep('''    ("slots", "Accessory slots", "bag",''', '''    ("slots", "Charm slots", "bag",''')
P.rep('''      "Off = the line stays in the bag, counts for nothing and the bag page says switched off.",''',
      '''      "Off = the line stays in Void Charms, counts for nothing and the Void Charms page says switched off.",''')
P.rep('''CRAFT_ROW = (CRAFT_KEY, "Craft from the bag", "bag",''', '''CRAFT_ROW = (CRAFT_KEY, "Craft in Void Charms", "bag",''')
P.rep('''             "The bag page's Craft tab - the only place accessories are crafted (off = no accessory crafting).",''',
      '''             "The Void Charms Craft tab - the only place accessories are crafted (off = no accessory crafting).",''')
P.rep('''            "A crafted accessory goes straight into the bag when it is a new line or better than the one in it.",''',
      '''            "A crafted accessory goes into Void Charms when it is a new line or better than the one in it.",''')
P.rep('''SND_SOUNDS = [["equip", "EQUIP", "Accessory equipped", "SFX_Drag_Items_Gems"], ["upgrade", "UPGRADE", "Accessory upgraded",''',
      '''SND_SOUNDS = [["equip", "EQUIP", "Charm equipped", "SFX_Drag_Items_Gems"], ["upgrade", "UPGRADE", "Charm upgraded",''')
P.rep("""('sound.equip', 'Accessory equipped sound', 'sounds', 'bool', 'true', '', '', '', '', 'live', 'An accessory went into a free bag slot. Off = silent.',""",
      """('sound.equip', 'Charm equipped sound', 'sounds', 'bool', 'true', '', '', '', '', 'live', 'A charm went into a free Void Charms slot. Off = silent.',""")
P.rep("""('sound.equip.id', 'Accessory equipped sound id',""", """('sound.equip.id', 'Charm equipped sound id',""")
P.rep("""('sound.upgrade', 'Accessory upgraded sound', 'sounds', 'bool', 'true', '', '', '', '', 'live', 'A better accessory of the same line replaced the old one in the bag. Off = silent.',""",
      """('sound.upgrade', 'Charm upgraded sound', 'sounds', 'bool', 'true', '', '', '', '', 'live', 'A better charm of the same line replaced the old one in Void Charms. Off = silent.',""")
P.rep("""('sound.upgrade.id', 'Accessory upgraded sound id',""", """('sound.upgrade.id', 'Charm upgraded sound id',""")

# ---- 2. file headers of NEW files (sounds: AccSnd.DEFAULT_TEXT + the kit DEFAULTS copy; config; power) + the ready log line
_SND_OLD = ("Server Setup -> Accessories -> Sounds,", "# Accessory equipped: An accessory went into a free bag slot.",
            "# Accessory upgraded: A better accessory of the same line replaced the old one in the bag.")
_SND_NEW = ("Server Setup -> Void Charms -> Sounds,", "# Charm equipped: A charm went into a free Void Charms slot.",
            "# Charm upgraded: A better charm of the same line replaced the old one in Void Charms.")
for _pre, _nl in (('"public static final String DEFAULT_TEXT = \\"# SkyyAccessories sounds (SkyWynn sound pass). Change them in game: SkyWynn Menu -> ', "\\\\n"),
                  ('"sounds.properties": \'# SkyyAccessories sounds (SkyWynn sound pass). Change them in game: SkyWynn Menu -> ', "\\n")):
    P.rep(_pre + _SND_OLD[0], _pre + _SND_NEW[0])
    P.rep("true" + _nl + _SND_OLD[1] + _nl + "sound.equip=true", "true" + _nl + _SND_NEW[1] + _nl + "sound.equip=true")
    P.rep("_Gems" + _nl + _SND_OLD[2] + _nl + "sound.upgrade=true", "_Gems" + _nl + _SND_NEW[2] + _nl + "sound.upgrade=true")
P.rep('''    "# SkyyAccessories settings. Change them in game: SkyWynn Menu -> Server Setup -> Accessories, or edit this file",''',
      '''    "# SkyyAccessories settings. Change them in game: SkyWynn Menu -> Server Setup -> Void Charms, or edit this file",''')
P.rep('''    "# SkyyAccessories - Accessory Power (0.5.22). Change it in game: SkyWynn Menu -> Server Setup -> Accessories -> Accessory Power,",''',
      '''    "# SkyyAccessories - Accessory Power (0.5.22). Change it in game: SkyWynn Menu -> Server Setup -> Void Charms -> Accessory Power,",''')
P.rep('''    "# Craft from the bag (0.5.18): the Void Charms page has a Craft tab with every accessory recipe. Crafting there needs no bench;",
    "# materials come from the inventory, then the Void, then the bag itself. Set craft.bag to false to switch the tab off.",''',
      '''    "# Craft in Void Charms (0.5.18): the Void Charms page has a Craft tab with every accessory recipe. Crafting there needs no bench;",
    "# materials come from the inventory, then the Void, then Void Charms itself. Set craft.bag to false to switch the tab off.",''')
P.rep('''    "# Auto-equip (0.5.18): an accessory a player crafts (bag page, bench or /craft) goes straight into the bag when the bag takes it - a",''',
      '''    "# Auto-equip (0.5.18): an accessory a player crafts (Void Charms page, bench or /craft) goes straight into Void Charms when it fits - a",''')
P.rep('admin settings: SkyWynn Menu -> Server Setup -> Accessories or /charms reload', 'admin settings: SkyWynn Menu -> Server Setup -> Void Charms or /charms reload')

# ---- 3. chat / page lines
P.rep('''  String res = "config " + sl + " bag slots, Regeneration every "''', '''  String res = "config " + sl + " charm slots, Regeneration every "''')
P.rep('''  if (!craftOn) res = res + ", the bag's Craft tab switched off";''', '''  if (!craftOn) res = res + ", the Void Charms Craft tab switched off";''')
P.rep('''NV_WHY = "Retired - the Lantern Accessory replaced it - craft one in the Craft tab of this bag"''',
      '''NV_WHY = "Retired - the Lantern Accessory replaced it - craft one in the Craft tab of Void Charms"''')
P.rep(''': "Bonuses - none yet - put accessories in this bag";''', ''': "Bonuses - none yet - put accessories in Void Charms";''')
P.rep('''    "OFF": "crafting from the bag is switched off on this server",''', '''    "OFF": "crafting in Void Charms is switched off on this server",''')
P.rep('''    if (ti >= t) return "your bag already has " +''', '''    if (ti >= t) return "your Void Charms already have " +''')
P.rep('''    return "upgraded to " + nm + " in your bag - your " +''', '''    return "upgraded to " + nm + " in your Void Charms - your " +''')
P.rep('''      where = "upgraded in your bag - " + accName(old) + (g == 0 ? " is back in your inventory" : (g == 1 ? " was kept in a free bag slot (inventory full)" :''',
      '''      where = "upgraded in your Void Charms - " + accName(old) + (g == 0 ? " is back in your inventory" : (g == 1 ? " was kept in a free Void Charms slot (inventory full)" :''')
P.rep('''    } else where = "it went straight into your bag";''', '''    } else where = "it went straight into your Void Charms";''')
P.rep('''(@PKG@.AccDefs.AUTO ? " or bag" : "")''', '''(@PKG@.AccDefs.AUTO ? " or Void Charms" : "")''')
P.rep('''"-your profile is still loading (put it on from the bag page)"''', '''"-your profile is still loading (put it on from the Void Charms page)"''')
P.rep('''("1".equals(g) ? " was kept in a free bag slot (inventory full)." :''', '''("1".equals(g) ? " was kept in a free Void Charms slot (inventory full)." :''')
P.rep('''      this.info = "your profile changed - this is the bag of your current profile now";''',
      '''      this.info = "your profile changed - these are the Void Charms of your current profile now";''')
P.finish()
